@startuml

interface User {
  + full_name : string
}

class Under_aged implements User {
  + student_card : string
}

class Adult implements User {
  + id_card : string
}

class Book {
  + title : string
  + author : string
}

class Borrow_History {
  + date : date
}

User "1" -- "*" Borrow_History
Borrow_History "*" --> "1" Book
User "0..1" -- "0..4" Book : borrows

@enduml

